    foreach(rc_targets($task) as $target){$observed=json_decode(file_get_contents(storage('research/calculation-pilot/independent/outputs.json')),true)['outputs'];$d['evidence']['calculation_reviews'][]=['task_id'=>$target['task']['id'],'result_id'=>$target['result']['id'],'calculation_id'=>$target['calculation']['id'],'verdict'=>$verdict,'method'=>$verdict==='reproduced'?'Independently executed the inspected archived model and original retained input in a fresh Node process; compared every output and its units.':'Independent unit review found the gas mass convention needs correction; revise the calculation and dependent conclusions.','environment'=>'Fresh local Node.js process with separate output directory and retained original input bytes.','run_log'=>'node model.mjs --input inputs.json --out D:/pilot/independent; process exit 0; output record retained.','observed_outputs'=>$verdict==='reproduced'?$observed:[]];}
    return $d;
